Code
sine_chart = (() =&gt; {
  const plot_container = html`&lt;div&gt;&lt;/div&gt;`;

  function render() {
    const x_hat = sine_amplitude_input.valueAsNumber;
    const omega = sine_omega_input.valueAsNumber;
    const phi = sine_phase_input.valueAsNumber;
    const dt = 0.01;
    const t_max = 10;
    const data = [];

    for (let t = 0; t &lt;= t_max; t += dt) {
      data.push({t, y: x_hat * Math.sin(omega * t + phi)});
    }

    sine_amplitude_label.textContent = `x̂: ${x_hat.toFixed(1)}`;
    sine_omega_label.textContent = `ω: ${omega.toFixed(0)} rad/s (${(omega / (2 * Math.PI)).toFixed(2)} Hz)`;
    sine_phase_label.textContent = `φ: ${phi.toFixed(2)} rad (${(phi * 180 / Math.PI).toFixed(0)}°)`;
    plot_container.replaceChildren(Plot.plot({
      height: 400,
      marginLeft: 60,
      marginBottom: 50,
      grid: true,
      style: {background: "transparent", color: "#333", fontSize: "14px"},
      x: {label: "Zeit [s]", domain: [0, 10]},
      y: {domain: [-5, 5], label: null},
      marks: [
        Plot.ruleY([0], {stroke: "#888", strokeDasharray: "4 4"}),
        Plot.lineY(data, {x: "t", y: "y", stroke: "#BF00BF", strokeWidth: 2.5})
      ]
    }));
  }

  sine_amplitude_input.addEventListener("input", render);
  sine_omega_input.addEventListener("input", render);
  sine_phase_input.addEventListener("input", render);
  render();
  invalidation.then(() =&gt; {
    sine_amplitude_input.removeEventListener("input", render);
    sine_omega_input.removeEventListener("input", render);
    sine_phase_input.removeEventListener("input", render);
  });
  return plot_container;
})();















WarnungTaschenrechner



Je nach Taschenrechner(-einstellung) muss beachtet werden, ob das Argument der Winkelfunktionen in Grad [°] oder Bogenmass [rad] angegeben werden muss (bzw. zurückgegeben wird im Falle der Arcusfunktionen). In Python (und anderen Programmiersprachen/Mathematikprogrammen) ist Bogenmass [rad] Standard.

3.2 Sinusantwort & Frequenzgang
In Anlehnung an die Sprungantwort können wir uns nun folgende Frage stellen:

Was passiert, wenn wir die Sinusschwingung Gleichung 3.1 mit einer bestimmten Frequenz \omega (und z. B. Amplitude 1) als Eingangssignal in ein Übertragungsglied einspeisen? Wie sieht das Ausgangssignal aus?







Abb. 3.2: Sinusförmige Anregung



☝️ Anders als bei der Sprungantwort speisen wir nun ein sinusförmiges Eingangssignal ein und sprechen daher von der Sinusantwort.






TippÜbung



Überlege dir, wie das Ausgangssignal gedanklich für ein P-Glied mit z. B. K_P = 2 aussehen könnte. Was ändert sich zwischen Ein- und Ausgangssignal? Was bleibt gleich? Wie könnte es bei einem P-T1-Glied aussehen?


Nachfolgende Simulation zeigt das Verhalten eines P-T1-Gliedes mit K_P = 2 und T_1 = 0.2\,\mathrm{s} auf eine sinusförmige Anregung. Beobachte was passiert, wenn die Frequenz der Anregung verändert wird. Was fällt auf?


