K = 2;
T = 0.2;
input_amplitude = 1;
dt = 1 / 60;
omegas = [0.1, 0.3, 1, 3, 10, 30];
buffer_window = 40;
window_durations = [40, 10, 2];

omega_label = html`&lt;span&gt;&lt;/span&gt;`;
frequency_input = html`&lt;input type="range" min="0" max="${omegas.length - 1}" step="1" value="0" aria-label="Kreisfrequenz" style="display:block;width:100%;cursor:pointer;accent-color:#2980b9;"&gt;`;

window_options = window_durations.map(duration =&gt; html`&lt;option value="${duration}" ${duration === window_durations[0] ? "selected" : ""}&gt;${duration} s&lt;/option&gt;`);
window_input = html`&lt;select id="time-window-select" aria-label="Zeitfenster" style="min-width:5.5em;padding:0.25em 0.5em;border:1px solid #999;border-radius:0.2em;background:#fff;color:#333;cursor:pointer;"&gt;${window_options}&lt;/select&gt;`;

html`
  &lt;div style="width:min(100%,800px);margin:0 auto 0.75em;"&gt;
    &lt;div style="font-size:1em;color:#333;margin-bottom:0.25em;text-align:center;"&gt;${omega_label}&lt;/div&gt;
    ${frequency_input}
    &lt;div style="display:flex;justify-content:space-between;margin:0.25em 0.4em 0;font-size:0.85em;color:#333;"&gt;
      ${omegas.map(w =&gt; html`&lt;span&gt;${w}&lt;/span&gt;`)}
    &lt;/div&gt;
  &lt;/div&gt;
`
























































































Code
window_samples = Math.round(buffer_window / dt) + 1;

chart_container = (() =&gt; {
  const plot_container = html`&lt;div style="margin-top:0.5em;"&gt;&lt;/div&gt;`;
  const legend_container = html`&lt;div&gt;&lt;/div&gt;`;
  const container = html`
    &lt;div style="display:flex;flex-direction:column;align-items:center;"&gt;
      ${plot_container}
      ${legend_container}
    &lt;/div&gt;
  `;
  const data = [];
  let t = 0;
  let output = 0;

  function addSample() {
    const selected_omega = omegas[Number(frequency_input.value)];
    t += dt;
    const input = input_amplitude * Math.sin(selected_omega * t);
    output += dt / T * (K * input - output);
    data.push({t, input, output});
  }

  for (let i = 0; i &lt; window_samples; i++) addSample();

  function render() {
    const selected_omega = omegas[Number(frequency_input.value)];
    const selected_window = Number(window_input.value);
    const x_max = data[data.length - 1].t;
    const x_min = Math.max(0, x_max - selected_window);
    const visible_data = data.filter(sample =&gt; sample.t &gt;= x_min);
    omega_label.textContent = `Kreisfrequenz ω = ${selected_omega} rad/s (${(selected_omega / (2 * Math.PI)).toFixed(2)} Hz)`;
    plot_container.replaceChildren(Plot.plot({
      height: 360,
      marginLeft: 95,
      marginTop: 45,
      marginBottom: 65,
      grid: true,
      style: {background: "transparent", color: "#333", fontSize: "14px"},
      x: {label: "Zeit [s]", labelAnchor: "center", domain: [x_min, Math.max(selected_window, x_max)]},
      y: {label: "Wert", labelAnchor: "center", domain: [-2.1, 2.1]},
      marks: [
        Plot.lineY(visible_data, {x: "t", y: "input", stroke: "#0000FF", strokeWidth: 2}),
        Plot.lineY(visible_data, {x: "t", y: "output", stroke: "#FF0000", strokeWidth: 2})
      ]
    }));
  }

  legend_container.replaceChildren(Plot.legend({
    color: {
      domain: ["Eingangssignal", "Ausgangssignal"],
      range: ["#0000FF", "#FF0000"]
    },
    style: {fontSize: "12px"}
  }));
  render();

  let elapsed = 0;
  let previous = performance.now();
  let frame;
  function update(now) {
    elapsed += Math.min((now - previous) / 1000, 0.1);
    previous = now;
    while (elapsed &gt;= dt) {
      elapsed -= dt;
      addSample();
      while (data.length &gt; window_samples) data.shift();
    }
    render();
    frame = requestAnimationFrame(update);
  }

  frame = requestAnimationFrame(update);
  invalidation.then(() =&gt; cancelAnimationFrame(frame));
  return container;
})();


















